/**
 * Render an invoice as plain text for display to customers.
 * Includes invoice number/DRAFT, customer name, line items with optional discounts,
 * voucher, VAT, and total. Also shows due date and amount paid if applicable.
 * @param {{ customerId: string, number?: string, status: string, dueDate?: string, lines: Array<{ qty: number, name: string, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: { code: string, amount: number }, payments?: Array<{ amount: number, date: string }> }} invoice
 * @returns {{ ok: true, value: string } | { ok: false, error: string }}
 */
export function renderInvoiceText(invoice) {
  // Get customer
  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;
  const lines = [];

  // Invoice number or DRAFT
  lines.push(invoice.number || 'DRAFT');

  // Customer name
  lines.push(customer.name);

  // Invoice lines with optional discount info
  for (const line of invoice.lines) {
    const lineTotal_ = lineTotal(line);
    const unitPriceStr = formatEuros(line.unitPrice);
    const lineTotalStr = formatEuros(lineTotal_);
    let lineStr = `${line.qty} x ${line.name} @ ${unitPriceStr} = ${lineTotalStr}`;

    // Add discount if present
    const discount = lineDiscount(line);
    if (discount > 0) {
      lineStr += ` (-${formatEuros(discount)})`;
    }

    lines.push(lineStr);
  }

  // Totals
  const totals = invoiceTotals(invoice);

  // Voucher if present
  if (totals.voucher > 0) {
    lines.push(`Voucher: -${formatEuros(totals.voucher)}`);
  }

  // VAT if present
  if (totals.vat > 0) {
    lines.push(`VAT: ${formatEuros(totals.vat)}`);
  }

  lines.push(`Total: ${formatEuros(totals.total)}`);

  // Due date if present
  if (invoice.dueDate) {
    lines.push(`Due: ${invoice.dueDate}`);
  }

  // Amount paid if payments exist
  if (invoice.payments && invoice.payments.length > 0) {
    const due = balanceDue(invoice);
    const paid = totals.total - due;
    lines.push(`Paid: ${formatEuros(paid)}`);
  }

  return ok(lines.join('\n'));
}

