6	test('renderInvoiceText renders a draft invoice', () => {
7	  const invoice = createInvoice({
8	    customerId: 'C-001',
9	    issueDate: '2026-10-07',
10	    lines: [{ sku: 'DES-HOUR', qty: 2 }],
11	  }).value;
12	
13	  const result = renderInvoiceText(invoice);
