20	  assert.ok(text.includes('€170.00'));
21	  assert.ok(text.includes('Total:'));
22	});
23	
24	test('renderInvoiceText renders an issued invoice', () => {
25	  const invoice = createInvoice({
26	    customerId: 'C-001',
27	    issueDate: '2026-10-07',
28	    lines: [{ sku: 'DES-HOUR', qty: 1 }],
29	  }).value;
30	  const issued = issueInvoice(invoice, []).value;
31	
32	  const result = renderInvoiceText(issued);
33	  assert.equal(result.ok, true);
34	  const text = result.value;
35	  assert.ok(text.includes('INV-2026-0001'));
36	  assert.ok(!text.includes('DRAFT'));
37	  assert.ok(text.includes('Northwind Studio'));
38	});
39	
