44	    lines: [{ sku: 'ICON-SET', qty: 100 }],
45	  }).value;
46	
47	  const result = renderInvoiceText(invoice);
48	  assert.equal(result.ok, true);
49	  const text = result.value;
50	  // 980 cents = €9.80, 100 × €9.80 = €980.00
51	  assert.ok(text.includes('€9.80'));
52	  assert.ok(text.includes('€980.00'));
53	});
54	
