test('renderInvoiceText shows bulk discount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  const result = renderInvoiceText(invoice);
  assert.equal(result.ok, true);
  const text = result.value;
  // qty 10 gets 2.5% bulk discount on the tier discount amount
  assert.ok(text.includes('(-€'));
