test('renderInvoiceText omits discount for lines without discount', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const result = renderInvoiceText(invoice);
  assert.equal(result.ok, true);
  const text = result.value;
  const lines = text.split('\n');
  // Line should not have discount info (C-002 is standard tier with 0% discount, and qty < 10)
  const lineItem = lines.find(l => l.includes('Design work'));
  assert.ok(lineItem);
  assert.ok(!lineItem.includes('(-€'));
});

test('renderInvoiceText shows voucher before total', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const withVoucher = applyVoucher(invoice, { code: 'SAVE10', amount: 5000 }).value;
  const result = renderInvoiceText(withVoucher);
  assert.equal(result.ok, true);
  const text = result.value;
  assert.ok(text.includes('Voucher: -€50.00'));

  // Verify voucher comes before total
  const lines = text.split('\n');
  const voucherIndex = lines.findIndex(l => l.includes('Voucher:'));
  const totalIndex = lines.findIndex(l => l.startsWith('Total:'));
  assert(voucherIndex >= 0);
  assert(voucherIndex < totalIndex);
});

test('renderInvoiceText shows due date when present', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const result = renderInvoiceText(issued);
  assert.equal(result.ok, true);
  const text = result.value;
  assert.ok(text.includes('Due: 2026-11-06'));
});

test('renderInvoiceText omits due date when not present', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const result = renderInvoiceText(invoice);
  assert.equal(result.ok, true);
  const text = result.value;
  assert.ok(!text.includes('Due:'));
});

test('renderInvoiceText shows amount paid', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const totals = invoiceTotals(issued);
  const paid = recordPayment(issued, { amount: totals.total / 2, date: '2026-10-15' }).value;

  const result = renderInvoiceText(paid);
  assert.equal(result.ok, true);
  const text = result.value;
  assert.ok(text.includes('Paid: €'));
  // Should show approximately half the total
  assert.ok(text.includes('Paid: €'));
});

test('renderInvoiceText omits paid line when no payments', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const result = renderInvoiceText(invoice);
  assert.equal(result.ok, true);
  const text = result.value;
  assert.ok(!text.includes('Paid:'));
});

test('renderInvoiceText shows paid for fully paid invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const totals = invoiceTotals(issued);
  const paid = recordPayment(issued, { amount: totals.total, date: '2026-10-15' }).value;

  const result = renderInvoiceText(paid);
  assert.equal(result.ok, true);
  const text = result.value;
  assert.ok(text.includes('Paid:'));
  assert.ok(text.includes('Paid: €'));
});

test('renderInvoiceText with everything: discount, voucher, due, and paid', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  }).value;

  let withVoucher = applyVoucher(invoice, { code: 'SAVE10', amount: 5000 }).value;
  const issued = issueInvoice(withVoucher, []).value;
  const totals = invoiceTotals(issued);
  const paid = recordPayment(issued, { amount: totals.total / 2, date: '2026-10-15' }).value;

  const result = renderInvoiceText(paid);
  assert.equal(result.ok, true);
  const text = result.value;

  // Verify all components are present
  assert.ok(text.includes('Northwind Studio'));
  assert.ok(text.includes('(-€')); // discount
  assert.ok(text.includes('Voucher: -€50.00'));
  assert.ok(text.includes('Due: 2026-11-06'));
  assert.ok(text.includes('Paid: €'));

  // Verify order: discount on line, voucher, VAT, total, due, paid
  const lines = text.split('\n');
  const discountLine = lines.findIndex(l => l.includes('(-€'));
  const voucherLine = lines.findIndex(l => l.includes('Voucher:'));
  const totalLine = lines.findIndex(l => l.startsWith('Total:'));
  const dueLine = lines.findIndex(l => l.startsWith('Due:'));
  const paidLine = lines.findIndex(l => l.startsWith('Paid:'));

  assert(discountLine >= 0);
  assert(voucherLine >= 0);
  assert(totalLine > voucherLine);
  assert(dueLine > totalLine);
  assert(paidLine > dueLine);
});

